INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('e0000001-0000-0000-0000-000000000001', NULL, '00000000-0000-0000-0001-000000000001', 999, 'examen-final-a1', '{"es": "Examen Final de Nivel A1", "en": "A1 Level Final Exam"}'::jsonb, '{"es": "Un examen que mezcla gramática, vocabulario, listening y funciones del lenguaje de todo el nivel A1. Necesitas 85% para certificarlo.", "en": "An exam mixing grammar, vocabulary, listening, and functional language from the whole A1 level. You need 85% to certify it."}'::jsonb, 'level_exam', 100, 30, '{"intro": "Este examen mezcla preguntas de todos los módulos de A1 que ya completaste. No es una lección nueva — es la certificación de que dominas el nivel completo. Necesitas al menos 85% para aprobar.", "sections": [{"type": "note", "variant": "warning", "text": "A diferencia de las lecciones normales, este examen toma una muestra aleatoria de un banco más grande de preguntas — si repruebas y reintentas, es probable que veas una combinación distinta."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation, tags) VALUES
('e0000002-0000-0000-0000-000000000001', 'e0000001-0000-0000-0000-000000000001', 1, 'multiple_choice', '{"text": "I ___ a teacher."}'::jsonb, '{"text": "am"}'::jsonb, '["is", "are"]'::jsonb, '{"es": "Con ''I'' siempre se usa ''am''."}'::jsonb, '{"grammar:to_be"}'),
('e0000002-0000-0000-0000-000000000002', 'e0000001-0000-0000-0000-000000000001', 2, 'multiple_choice', '{"text": "She ___ from Peru. (negativo)"}'::jsonb, '{"text": "isn''t"}'::jsonb, '["don''t", "doesn''t"]'::jsonb, '{"es": "La negación de to be con ella es ''isn''t'', no ''doesn''t''."}'::jsonb, '{"grammar:to_be"}'),
('e0000002-0000-0000-0000-000000000003', 'e0000001-0000-0000-0000-000000000001', 3, 'fill_blank', '{"text": "I have two ___. (perro)"}'::jsonb, '{"text": "dogs", "accepted": ["dogs"]}'::jsonb, NULL, '{"es": "Plural regular: dog + s = dogs."}'::jsonb, '{"grammar:plurals"}'),
('e0000002-0000-0000-0000-000000000004', 'e0000001-0000-0000-0000-000000000001', 4, 'fill_blank', '{"text": "I need ___ umbrella. (paraguas)"}'::jsonb, '{"text": "an", "accepted": ["an"]}'::jsonb, NULL, '{"es": "''Umbrella'' empieza con vocal, así que se usa ''an''."}'::jsonb, '{"grammar:articles"}'),
('e0000002-0000-0000-0000-000000000005', 'e0000001-0000-0000-0000-000000000001', 5, 'multiple_choice', '{"text": "She ___ coffee every morning."}'::jsonb, '{"text": "drinks"}'::jsonb, '["drink", "drinking"]'::jsonb, '{"es": "Tercera persona en presente simple lleva -s: drinks."}'::jsonb, '{"grammar:present_simple"}'),
('e0000002-0000-0000-0000-000000000006', 'e0000001-0000-0000-0000-000000000001', 6, 'error_correction', '{"text": "He don''t like tea.", "error_word": "don''t"}'::jsonb, '{"text": "doesn''t"}'::jsonb, '["not", "isn''t"]'::jsonb, '{"es": "Con ''he'' la negación correcta es ''doesn''t''."}'::jsonb, '{"grammar:present_simple"}'),
('e0000002-0000-0000-0000-000000000007', 'e0000001-0000-0000-0000-000000000001', 7, 'multiple_choice', '{"text": "___ a book on the table."}'::jsonb, '{"text": "There is"}'::jsonb, '["There are", "It is"]'::jsonb, '{"es": "''Book'' es singular, así que se usa ''there is''."}'::jsonb, '{"grammar:there_is_are"}'),
('e0000002-0000-0000-0000-000000000008', 'e0000001-0000-0000-0000-000000000001', 8, 'word_bank_fill', '{"text": "___ you like pizza?"}'::jsonb, '{"answers": ["Do"]}'::jsonb, '["Does", "Are"]'::jsonb, '{"es": "Con ''you'' y un verbo de acción se usa ''do''."}'::jsonb, '{"grammar:questions"}'),
('e0000002-0000-0000-0000-000000000009', 'e0000001-0000-0000-0000-000000000001', 9, 'multiple_choice', '{"text": "___ is your birthday?"}'::jsonb, '{"text": "When"}'::jsonb, '["Where", "Who"]'::jsonb, '{"es": "''When'' pregunta por un momento en el tiempo."}'::jsonb, '{"grammar:question_words"}'),
('e0000002-0000-0000-0000-000000000010', 'e0000001-0000-0000-0000-000000000001', 10, 'multiple_choice', '{"text": "I ___ swim very well."}'::jsonb, '{"text": "can"}'::jsonb, '["do", "am"]'::jsonb, '{"es": "''Can'' expresa habilidad."}'::jsonb, '{"grammar:can"}'),
('e0000002-0000-0000-0000-000000000011', 'e0000001-0000-0000-0000-000000000001', 11, 'translation', '{"text": "Mi hermana tiene veinte años."}'::jsonb, '{"text": "My sister is twenty years old.", "accepted": ["My sister is twenty years old."]}'::jsonb, NULL, '{"es": "La edad siempre va con to be: ''is twenty years old''."}'::jsonb, '{"vocab:family","grammar:to_be"}'),
('e0000002-0000-0000-0000-000000000012', 'e0000001-0000-0000-0000-000000000001', 12, 'reverse_translation', '{"text": "I have three brothers."}'::jsonb, '{"accepted": ["Tengo tres hermanos."]}'::jsonb, NULL, NULL, '{"vocab:family"}'),
('e0000002-0000-0000-0000-000000000013', 'e0000001-0000-0000-0000-000000000001', 13, 'word_match', '{"text": "Une cada palabra con su traducción."}'::jsonb, '{"pairs": [{"en": "mother", "es": "madre"}, {"en": "father", "es": "padre"}, {"en": "sister", "es": "hermana"}, {"en": "brother", "es": "hermano"}]}'::jsonb, NULL, NULL, '{"vocab:family"}'),
('e0000002-0000-0000-0000-000000000014', 'e0000001-0000-0000-0000-000000000001', 14, 'multiple_choice', '{"text": "¿Cómo se dice ''45'' en inglés?"}'::jsonb, '{"text": "forty-five"}'::jsonb, '["fourty-five", "forty-fifth"]'::jsonb, NULL, '{"vocab:numbers"}'),
('e0000002-0000-0000-0000-000000000015', 'e0000001-0000-0000-0000-000000000001', 15, 'fill_blank', '{"text": "It''s three ___. (en punto)"}'::jsonb, '{"text": "o''clock", "accepted": ["o''clock"]}'::jsonb, NULL, NULL, '{"vocab:time"}'),
('e0000002-0000-0000-0000-000000000016', 'e0000001-0000-0000-0000-000000000001', 16, 'multiple_choice', '{"text": "What day comes after Monday?"}'::jsonb, '{"text": "Tuesday"}'::jsonb, '["Sunday", "Wednesday"]'::jsonb, NULL, '{"vocab:dates"}'),
('e0000002-0000-0000-0000-000000000017', 'e0000001-0000-0000-0000-000000000001', 17, 'multiple_choice', '{"text": "The sky is ___."}'::jsonb, '{"text": "blue"}'::jsonb, '["green", "yellow"]'::jsonb, NULL, '{"vocab:colors"}'),
('e0000002-0000-0000-0000-000000000018', 'e0000001-0000-0000-0000-000000000001', 18, 'multiple_choice', '{"text": "This bag is very ___. (pesada)"}'::jsonb, '{"text": "heavy"}'::jsonb, '["light", "small"]'::jsonb, NULL, '{"vocab:adjectives"}'),
('e0000002-0000-0000-0000-000000000019', 'e0000001-0000-0000-0000-000000000001', 19, 'fill_blank', '{"text": "I eat an ___ every morning. (manzana)"}'::jsonb, '{"text": "apple", "accepted": ["apple"]}'::jsonb, NULL, NULL, '{"vocab:food"}'),
('e0000002-0000-0000-0000-000000000020', 'e0000001-0000-0000-0000-000000000001', 20, 'dialogue_fill', '{"lines": [{"speaker": "A", "text": "Can I have the menu, please?"}, {"speaker": "B", "text": "___"}, {"speaker": "A", "text": "Thank you!"}]}'::jsonb, '{"text": "Of course, here you go."}'::jsonb, '["I don''t like vegetables.", "It''s Monday.", "She has blue eyes."]'::jsonb, NULL, '{"vocab:food","functional_language"}'),
('e0000002-0000-0000-0000-000000000021', 'e0000001-0000-0000-0000-000000000001', 21, 'multiple_choice', '{"text": "You use your ___ to see."}'::jsonb, '{"text": "eyes"}'::jsonb, '["ears", "hands"]'::jsonb, NULL, '{"vocab:body"}'),
('e0000002-0000-0000-0000-000000000022', 'e0000001-0000-0000-0000-000000000001', 22, 'fill_blank', '{"text": "I have a ___. (dolor de cabeza)"}'::jsonb, '{"text": "headache", "accepted": ["headache"]}'::jsonb, NULL, NULL, '{"vocab:body"}'),
('e0000002-0000-0000-0000-000000000023', 'e0000001-0000-0000-0000-000000000001', 23, 'multiple_choice', '{"text": "This is ___ book, not yours."}'::jsonb, '{"text": "my"}'::jsonb, '["me", "I"]'::jsonb, NULL, '{"grammar:pronouns"}'),
('e0000002-0000-0000-0000-000000000024', 'e0000001-0000-0000-0000-000000000001', 24, 'multiple_choice', '{"text": "Can you help ___? (a mí)"}'::jsonb, '{"text": "me"}'::jsonb, '["I", "my"]'::jsonb, NULL, '{"grammar:pronouns"}'),
('e0000002-0000-0000-0000-000000000025', 'e0000001-0000-0000-0000-000000000001', 25, 'multiple_choice', '{"text": "¿Cómo pides que repitan algo?"}'::jsonb, '{"text": "Can you repeat that, please?"}'::jsonb, '["I am fine, thanks.", "It''s over there."]'::jsonb, NULL, '{"functional_language"}'),
('e0000002-0000-0000-0000-000000000026', 'e0000001-0000-0000-0000-000000000001', 26, 'reorder_words', '{"text": "Ordena la oración: live / I / in / Bogotá"}'::jsonb, '{"text": "I live in Bogotá"}'::jsonb, NULL, NULL, '{"grammar:present_simple"}'),
('e0000002-0000-0000-0000-000000000027', 'e0000001-0000-0000-0000-000000000001', 27, 'listening', '{"text": "Escucha y elige el significado.", "audio_text": "Where do you live?"}'::jsonb, '{"text": "¿Dónde vives?"}'::jsonb, '["¿Cómo te llamas?", "¿Cuántos años tienes?", "¿De dónde eres?"]'::jsonb, NULL, '{"grammar:question_words"}'),
('e0000002-0000-0000-0000-000000000028', 'e0000001-0000-0000-0000-000000000001', 28, 'dictation', '{"text": "Escucha y escribe la frase.", "audio_text": "She has a big family."}'::jsonb, '{"accepted": ["She has a big family.", "She has a big family"]}'::jsonb, NULL, NULL, '{"vocab:family"}'),
('e0000002-0000-0000-0000-000000000029', 'e0000001-0000-0000-0000-000000000001', 29, 'minimal_pairs', '{"text": "Escucha y elige la palabra que oíste.", "audio_text": "ship"}'::jsonb, '{"text": "ship"}'::jsonb, '["sheep"]'::jsonb, NULL, '{"phonetics"}'),
('e0000002-0000-0000-0000-000000000030', 'e0000001-0000-0000-0000-000000000001', 30, 'multiple_choice', '{"text": "___ the door, please. (cierra)"}'::jsonb, '{"text": "Close"}'::jsonb, '["Closes", "Closing"]'::jsonb, NULL, '{"grammar:imperatives"}');
